BEGIN TRANSACTION;
CREATE TABLE asset_types (
	asset_type_id INTEGER NOT NULL, 
	type_name VARCHAR(100) NOT NULL, 
	description TEXT, 
	expected_return_days INTEGER NOT NULL, 
	deposit_amount NUMERIC(12, 2) NOT NULL, 
	is_active BOOLEAN NOT NULL, 
	PRIMARY KEY (asset_type_id), 
	CONSTRAINT ck_asset_type_return_days CHECK (expected_return_days > 0), 
	CONSTRAINT ck_asset_type_deposit CHECK (deposit_amount >= 0), 
	UNIQUE (type_name)
);
CREATE TABLE custody_events (
	event_id INTEGER NOT NULL, 
	event_code VARCHAR(100), 
	asset_id INTEGER NOT NULL, 
	shipment_id INTEGER, 
	from_location_id INTEGER, 
	to_location_id INTEGER NOT NULL, 
	actor_name VARCHAR(150), 
	event_type VARCHAR(30) NOT NULL, 
	event_timestamp DATETIME NOT NULL, 
	notes TEXT, 
	PRIMARY KEY (event_id), 
	CONSTRAINT ck_custody_event_type CHECK (event_type IN ('dispatch', 'transfer', 'receipt', 'return')), 
	UNIQUE (event_code), 
	FOREIGN KEY(asset_id) REFERENCES reusable_assets (asset_id), 
	FOREIGN KEY(shipment_id) REFERENCES shipments (shipment_id), 
	FOREIGN KEY(from_location_id) REFERENCES locations (location_id), 
	FOREIGN KEY(to_location_id) REFERENCES locations (location_id)
);
CREATE TABLE deposit_ledger (
	ledger_id INTEGER NOT NULL, 
	asset_id INTEGER NOT NULL, 
	shipment_id INTEGER, 
	transaction_type VARCHAR(30) NOT NULL, 
	amount NUMERIC(12, 2) NOT NULL, 
	transaction_date DATETIME NOT NULL, 
	reference_code VARCHAR(100) NOT NULL, 
	notes TEXT, 
	PRIMARY KEY (ledger_id), 
	CONSTRAINT ck_deposit_transaction_type CHECK (transaction_type IN ('charge', 'refund', 'adjustment')), 
	CONSTRAINT ck_deposit_amount CHECK (amount > 0), 
	FOREIGN KEY(asset_id) REFERENCES reusable_assets (asset_id), 
	FOREIGN KEY(shipment_id) REFERENCES shipments (shipment_id), 
	UNIQUE (reference_code)
);
CREATE TABLE inspections (
	inspection_id INTEGER NOT NULL, 
	asset_id INTEGER NOT NULL, 
	return_id INTEGER, 
	inspector_name VARCHAR(150) NOT NULL, 
	inspection_date DATETIME NOT NULL, 
	condition_status VARCHAR(30) NOT NULL, 
	remarks TEXT, 
	PRIMARY KEY (inspection_id), 
	CONSTRAINT ck_inspection_condition CHECK (condition_status IN ('good', 'damaged', 'unusable')), 
	FOREIGN KEY(asset_id) REFERENCES reusable_assets (asset_id), 
	FOREIGN KEY(return_id) REFERENCES return_authorizations (return_id)
);
CREATE TABLE locations (
	location_id INTEGER NOT NULL, 
	location_name VARCHAR(150) NOT NULL, 
	location_type VARCHAR(30) NOT NULL, 
	city VARCHAR(100) NOT NULL, 
	state VARCHAR(100) NOT NULL, 
	country VARCHAR(100) NOT NULL, 
	is_active BOOLEAN NOT NULL, 
	PRIMARY KEY (location_id)
);
CREATE TABLE operational_exceptions (
	exception_id VARCHAR(50) NOT NULL, 
	issue_type VARCHAR(50) NOT NULL, 
	affected_entity VARCHAR(50) NOT NULL, 
	affected_record_id VARCHAR(50) NOT NULL, 
	severity VARCHAR(20) NOT NULL, 
	detected_at DATETIME NOT NULL, 
	detection_result TEXT NOT NULL, 
	resolution_status VARCHAR(30) NOT NULL, 
	resolution_notes TEXT, 
	updated_at DATETIME, 
	PRIMARY KEY (exception_id), 
	CONSTRAINT ck_exception_resolution_status CHECK (resolution_status IN ('Open', 'Under Review', 'Resolved'))
);
CREATE TABLE owners (
	owner_id INTEGER NOT NULL, 
	owner_name VARCHAR(150) NOT NULL, 
	owner_type VARCHAR(30) NOT NULL, 
	contact_email VARCHAR(150), 
	is_active BOOLEAN NOT NULL, 
	PRIMARY KEY (owner_id), 
	UNIQUE (owner_name)
);
CREATE TABLE repairs (
	repair_id INTEGER NOT NULL, 
	repair_code VARCHAR(50), 
	asset_id INTEGER NOT NULL, 
	inspection_id INTEGER, 
	repair_description TEXT NOT NULL, 
	repair_cost NUMERIC(12, 2) NOT NULL, 
	repair_status VARCHAR(30) NOT NULL, 
	opened_at DATETIME NOT NULL, 
	closed_at DATETIME, 
	PRIMARY KEY (repair_id), 
	CONSTRAINT ck_repair_cost CHECK (repair_cost >= 0), 
	CONSTRAINT ck_repair_status CHECK (repair_status IN ('open', 'in_progress', 'completed')), 
	UNIQUE (repair_code), 
	FOREIGN KEY(asset_id) REFERENCES reusable_assets (asset_id), 
	FOREIGN KEY(inspection_id) REFERENCES inspections (inspection_id)
);
CREATE TABLE return_authorizations (
	return_id INTEGER NOT NULL, 
	return_code VARCHAR(50) NOT NULL, 
	asset_id INTEGER NOT NULL, 
	shipment_id INTEGER, 
	requested_by VARCHAR(150) NOT NULL, 
	request_date DATETIME NOT NULL, 
	approved_date DATETIME, 
	return_status VARCHAR(30) NOT NULL, 
	PRIMARY KEY (return_id), 
	CONSTRAINT ck_return_status CHECK (return_status IN ('requested', 'approved', 'received', 'rejected', 'cancelled')), 
	UNIQUE (return_code), 
	FOREIGN KEY(asset_id) REFERENCES reusable_assets (asset_id), 
	FOREIGN KEY(shipment_id) REFERENCES shipments (shipment_id)
);
CREATE TABLE reusable_assets (
	asset_id INTEGER NOT NULL, 
	asset_code VARCHAR(50) NOT NULL, 
	asset_type_id INTEGER NOT NULL, 
	owner_id INTEGER NOT NULL, 
	serial_number VARCHAR(100), 
	manufacture_date DATE, 
	lifecycle_status VARCHAR(30) NOT NULL, 
	created_at DATETIME NOT NULL, 
	PRIMARY KEY (asset_id), 
	CONSTRAINT ck_asset_lifecycle_status CHECK (lifecycle_status IN ('available', 'in_transit', 'in_use', 'under_repair', 'lost', 'retired')), 
	UNIQUE (asset_code), 
	FOREIGN KEY(asset_type_id) REFERENCES asset_types (asset_type_id), 
	FOREIGN KEY(owner_id) REFERENCES owners (owner_id)
);
CREATE TABLE shipments (
	shipment_id INTEGER NOT NULL, 
	shipment_code VARCHAR(50) NOT NULL, 
	origin_location_id INTEGER NOT NULL, 
	destination_location_id INTEGER NOT NULL, 
	carrier_name VARCHAR(150) NOT NULL, 
	dispatch_date DATETIME NOT NULL, 
	expected_delivery_date DATETIME, 
	actual_delivery_date DATETIME, 
	shipment_status VARCHAR(30) NOT NULL, 
	PRIMARY KEY (shipment_id), 
	CONSTRAINT ck_shipment_different_locations CHECK (origin_location_id != destination_location_id), 
	CONSTRAINT ck_shipment_status CHECK (shipment_status IN ('planned', 'dispatched', 'delivered', 'cancelled')), 
	UNIQUE (shipment_code), 
	FOREIGN KEY(origin_location_id) REFERENCES locations (location_id), 
	FOREIGN KEY(destination_location_id) REFERENCES locations (location_id)
);
CREATE INDEX ix_owners_owner_id ON owners (owner_id);
CREATE INDEX ix_locations_location_id ON locations (location_id);
CREATE INDEX ix_asset_types_asset_type_id ON asset_types (asset_type_id);
CREATE INDEX ix_operational_exceptions_affected_record_id ON operational_exceptions (affected_record_id);
CREATE INDEX ix_operational_exceptions_exception_id ON operational_exceptions (exception_id);
CREATE INDEX ix_exception_issue_status ON operational_exceptions (issue_type, resolution_status);
CREATE INDEX ix_operational_exceptions_issue_type ON operational_exceptions (issue_type);
CREATE INDEX ix_reusable_assets_asset_id ON reusable_assets (asset_id);
CREATE INDEX ix_asset_owner ON reusable_assets (owner_id);
CREATE INDEX ix_asset_type ON reusable_assets (asset_type_id);
CREATE INDEX ix_shipment_status ON shipments (shipment_status);
CREATE INDEX ix_shipments_shipment_id ON shipments (shipment_id);
CREATE INDEX ix_custody_asset_timestamp ON custody_events (asset_id, event_timestamp);
CREATE INDEX ix_custody_events_event_id ON custody_events (event_id);
CREATE INDEX ix_return_authorizations_return_id ON return_authorizations (return_id);
CREATE INDEX ix_deposit_ledger_ledger_id ON deposit_ledger (ledger_id);
CREATE INDEX ix_deposit_asset ON deposit_ledger (asset_id);
CREATE INDEX ix_inspections_inspection_id ON inspections (inspection_id);
CREATE INDEX ix_repairs_repair_id ON repairs (repair_id);
COMMIT;
